#include <stdio.h>
int main() {
    int N, M, salon, estudiante;
    float nota, sumaSalon, sumaPromedios, promedioSalon, promedioGeneral;
    scanf("%d %d", &N, &M);
    sumaPromedios = 0;
    salon = 1;
    while (salon <= N) {
        sumaSalon = 0;
        estudiante = 1;
        while (estudiante <= M) {
            scanf("%f", &nota);
            sumaSalon += nota;
            estudiante++;
        }
        promedioSalon = sumaSalon / M;
        printf("Salon %d: promedio %.2f\n", salon, promedioSalon);
        sumaPromedios += promedioSalon;
        salon++;
    }
    promedioGeneral = sumaPromedios / N;
    printf("Promedio general: %.2f\n", promedioGeneral);
    return 0;
}
